t.script:
document.addEventListener('DOMContentLoaded', function() {
    var ctx = document.getElementById('costDistributionChart').getContext('2d');
    var myChart = new Chart(ctx, {
        type: 'doughnut',
        data: {
            labels: ['Equipos', 'Mano de Obra', 'Materiales', 'Transporte'],
            datasets: [{
                data: [, , , ],
                backgroundColor: ['#3498db', '#2ecc71', '#f39c12', '#1abc9c'],
                borderWidth: 0
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: { position: 'bottom' }
            },
            cutout: '70%'
        }
    });
});

function geosisFilterResources() {
    const categorySelect = document.getElementById('geosis-rubro-category');
    const resourceSelect = document.getElementById('geosis-rubro-resource');
    if (!categorySelect || !resourceSelect) {
        return;
    }
    const category = categorySelect.value;
    let firstVisible = null;
    Array.from(resourceSelect.options).forEach((option) => {
        const visible = option.dataset.category === category;
        option.hidden = !visible;
        if (visible && !firstVisible) {
            firstVisible = option;
        }
    });
    if (firstVisible) {
        resourceSelect.value = firstVisible.value;
    }
    geosisSyncResourceForm();
}

function geosisSyncResourceForm() {
    const resourceSelect = document.getElementById('geosis-rubro-resource');
    const categorySelect = document.getElementById('geosis-rubro-category');
    const rateInput = document.getElementById('geosis-rubro-rate');
    const uomInput = document.getElementById('geosis-rubro-uom');
    if (!resourceSelect) {
        return;
    }
    const selected = resourceSelect.options[resourceSelect.selectedIndex];
    if (!selected) {
        return;
    }
    if (categorySelect && selected.dataset.category) {
        categorySelect.value = selected.dataset.category;
    }
    if (rateInput) {
        rateInput.value = selected.dataset.price || '0';
    }
    if (uomInput) {
        uomInput.value = selected.dataset.uom || '';
    }
    geosisComputeResourceCost();
}

function geosisComputeResourceCost() {
    const quantity = parseFloat(document.getElementById('geosis-rubro-quantity')?.value || '0');
    const rate = parseFloat(document.getElementById('geosis-rubro-rate')?.value || '0');
    const performance = parseFloat(document.getElementById('geosis-rubro-performance')?.value || '0');
    const output = document.getElementById('geosis-rubro-estimated-cost');
    if (!output) {
        return;
    }
    output.textContent = '$' + (quantity * rate * performance).toFixed(2);
}

function geosisToggleEditLine(lineId) {
    const el = document.getElementById('edit-line-' + lineId);
    if (el) {
        el.classList.toggle('d-none');
    }
}

geosisFilterResources();
